/**
 * Board View Component
 * Shows items in a board, organized by columns (as tabs)
 */

import { createElement, clearElement, icons } from "../lib/dom";
import { widgetStore, actions } from "../lib/state";
import { getClient } from "../lib/api";

let currentColumnFilter: string | null = null;

export function renderBoardView(container: HTMLElement) {
  const state = widgetStore.get();
  clearElement(container);

  if (!state.currentBoard) {
    container.textContent = "No board selected";
    return;
  }

  // Column tabs
  const tabs = createElement("div", { className: "uv-tabs" });

  // "All" tab
  const allTab = createElement("button", {
    className: "uv-tab",
    dataset: { active: currentColumnFilter === null ? "true" : "false" },
  }, ["All"]);
  allTab.addEventListener("click", () => {
    currentColumnFilter = null;
    renderBoardView(container);
  });
  tabs.appendChild(allTab);

  // Column tabs
  state.columns.forEach((column: any) => {
    const tab = createElement("button", {
      className: "uv-tab",
      dataset: { active: currentColumnFilter === column._id ? "true" : "false" },
    }, [column.name]);
    tab.addEventListener("click", () => {
      currentColumnFilter = column._id;
      renderBoardView(container);
    });
    tabs.appendChild(tab);
  });

  container.appendChild(tabs);

  // Content
  const content = createElement("div", { className: "uv-content" });

  // Filter items by column if selected
  let displayItems = state.items;
  if (currentColumnFilter) {
    displayItems = state.items.filter((item: any) => item.columnId === currentColumnFilter);
  }

  // Sort by vote count descending
  displayItems = [...displayItems].sort((a: any, b: any) => b.voteCount - a.voteCount);

  if (displayItems.length === 0) {
    const emptyDiv = createElement("div", { className: "uv-empty" });
    const emptyIcon = createElement("div", { className: "uv-empty-icon" }, ["📭"]);
    const emptyText = createElement("p", {}, ["No items yet. Be the first to add one!"]);
    emptyDiv.appendChild(emptyIcon);
    emptyDiv.appendChild(emptyText);
    content.appendChild(emptyDiv);
  } else {
    const cardList = createElement("div", { className: "uv-card-list" });

    displayItems.forEach((item: any) => {
      const card = renderItemCard(item, state);
      cardList.appendChild(card);
    });

    content.appendChild(cardList);
  }

  // Add button (if board allows submissions)
  if (state.currentBoard.allowUserSubmissions) {
    const addBtn = createElement("button", { className: "uv-add-btn" }, [
      "+ Add " + getBoardItemLabel(state.currentBoard.slug),
    ]);
    addBtn.addEventListener("click", () => {
      if (!state.isAuthenticated) {
        actions.showAuth();
      } else {
        showAddItemModal(container);
      }
    });
    content.appendChild(addBtn);
  }

  container.appendChild(content);
}

function renderItemCard(item: any, state: any): HTMLElement {
  const card = createElement("div", { className: "uv-card" });

  const header = createElement("div", { className: "uv-card-header" });

  // Content section
  const contentDiv = createElement("div", { className: "uv-card-content" });
  const title = createElement("h4", { className: "uv-card-title" }, [item.title]);
  contentDiv.appendChild(title);

  if (item.description) {
    const description = createElement("p", { className: "uv-card-description" }, [item.description]);
    contentDiv.appendChild(description);
  }

  // Meta section
  const meta = createElement("div", { className: "uv-card-meta" });

  // Find column name
  const column = state.columns.find((c: any) => c._id === item.columnId);
  if (column) {
    const statusBadge = createElement("span", { className: "uv-badge uv-badge-status" });
    const indicator = createElement("span", {
      className: "uv-status-indicator",
      dataset: { status: column.slug },
    });
    statusBadge.appendChild(indicator);
    statusBadge.appendChild(document.createTextNode(column.name));
    meta.appendChild(statusBadge);
  }

  contentDiv.appendChild(meta);
  header.appendChild(contentDiv);

  // Vote button
  const hasVoted = state.userVotes.has(item._id);
  const voteBtn = createElement("button", {
    className: "uv-vote-btn",
    dataset: { voted: hasVoted ? "true" : "false" },
  });

  const voteIcon = createElement("span");
  voteIcon.innerHTML = icons.arrowUp;
  voteIcon.style.display = "flex";
  const voteCount = createElement("span", { className: "uv-vote-count" }, [String(item.voteCount)]);

  voteBtn.appendChild(voteIcon);
  voteBtn.appendChild(voteCount);

  voteBtn.addEventListener("click", async () => {
    if (!state.isAuthenticated) {
      actions.showAuth();
      return;
    }

    const client = getClient();
    if (!client) return;

    // Optimistic update
    actions.toggleVote(item._id, !hasVoted);

    try {
      if (hasVoted) {
        await client.unvote(item._id);
      } else {
        await client.vote(item._id);
      }
    } catch (error) {
      // Revert on error
      actions.toggleVote(item._id, hasVoted);
    }
  });

  header.appendChild(voteBtn);
  card.appendChild(header);

  return card;
}

function getBoardItemLabel(slug: string): string {
  switch (slug) {
    case "feature-requests":
      return "Feature Request";
    case "bug-reports":
      return "Bug Report";
    default:
      return "Item";
  }
}

function showAddItemModal(_container: HTMLElement) {
  const state = widgetStore.get();

  // Create modal overlay
  const overlay = createElement("div", { className: "uv-modal-overlay" });

  const modal = createElement("div", { className: "uv-modal" });

  // Header
  const header = createElement("div", { className: "uv-modal-header" });
  const title = createElement("h3", { className: "uv-modal-title" }, [
    "Add " + getBoardItemLabel(state.currentBoard?.slug || ""),
  ]);
  const closeBtn = createElement("button", { className: "uv-modal-close" });
  closeBtn.innerHTML = icons.close;
  closeBtn.addEventListener("click", () => overlay.remove());
  header.appendChild(title);
  header.appendChild(closeBtn);
  modal.appendChild(header);

  // Form
  const form = createElement("form", { className: "uv-form" });

  // Title input
  const titleGroup = createElement("div", { className: "uv-form-group" });
  const titleLabel = createElement("label", { className: "uv-label" }, ["Title"]);
  const titleInput = createElement("input", {
    className: "uv-input",
    type: "text",
    placeholder: "Brief summary of your idea",
  } as any);
  titleInput.required = true;
  titleGroup.appendChild(titleLabel);
  titleGroup.appendChild(titleInput);
  form.appendChild(titleGroup);

  // Description input
  const descGroup = createElement("div", { className: "uv-form-group" });
  const descLabel = createElement("label", { className: "uv-label" }, ["Description (optional)"]);
  const descInput = createElement("textarea", {
    className: "uv-textarea",
    placeholder: "Provide more details about your suggestion...",
  } as any);
  descGroup.appendChild(descLabel);
  descGroup.appendChild(descInput);
  form.appendChild(descGroup);

  // Error message
  const errorDiv = createElement("div", { className: "uv-error" });
  errorDiv.style.display = "none";
  form.appendChild(errorDiv);

  // Submit button
  const submitBtn = createElement("button", {
    className: "uv-submit-btn",
    type: "submit",
  } as any, ["Submit"]);
  form.appendChild(submitBtn);

  form.addEventListener("submit", async (e) => {
    e.preventDefault();

    const client = getClient();
    if (!client || !state.selectedBoardId) return;

    submitBtn.disabled = true;
    submitBtn.textContent = "Submitting...";
    errorDiv.style.display = "none";

    try {
      const result = await client.createItem(
        state.selectedBoardId,
        titleInput.value,
        descInput.value || undefined
      );

      if (result.success) {
        // Refresh items
        const items = await client.getBoardItems(state.selectedBoardId);
        actions.setItems(items);
        overlay.remove();
      } else {
        errorDiv.textContent = result.error || "Failed to create item";
        errorDiv.style.display = "block";
      }
    } catch (error: any) {
      errorDiv.textContent = error.message || "An error occurred";
      errorDiv.style.display = "block";
    } finally {
      submitBtn.disabled = false;
      submitBtn.textContent = "Submit";
    }
  });

  modal.appendChild(form);
  overlay.appendChild(modal);

  // Close on overlay click
  overlay.addEventListener("click", (e) => {
    if (e.target === overlay) {
      overlay.remove();
    }
  });

  document.body.appendChild(overlay);
}
